def retain(self, name, value):
    if name == 'gate_output' and self.gate_destination is not None:
        # Preserve the decoder owner's explicit host retention option.
        # All other captures keep this backend's original borrowed path.
        return super().retain(name, value)
    if getattr(self, 'retained_names', None) is None or name in self.retained_names:
        self.values[name] = self._actual(name, value, self.destination)

